// composedAssertGetZeroOnError asserts Get returns zero alongside any error.
func composedAssertGetZeroOnError(
	tb testing.TB,
	c Composed,
	fx ComposedFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := c.Get(ctx, fx.Key())
	if err == nil {
		tb.Skip("Get answered for a cancelled context, so this check has no error to inspect")
	}

	var zero string
	if got != zero {
		tb.Errorf("Get must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

